        (void)(m_assertAlmostEqual(Args({(((rd(L_plate, V(0.0)) + rd(L_plate, V(2.0))) / V(2.0)) + L_dx), ((rd(L_head, V(0.0)) + rd(L_head, V(2.0))) / V(2.0))}, {{SY("delta"), pm_test_pvp_giant_imp_headgear::TOLERANCE}, {SY("msg"), (L_armor + SV(" centre"))}})));
