V C_GiantRidingImpHeadgearTests::m_test_magnet_fits_one_piece_at_a_time(const Args& A) {
    V L_b;
    V L_unit;
    { V ut1_ = py::as_seq(m_giant(Args({}, {{SY("riding_armor"), V::none()}}))); L_b = ut1_.idx(0); L_unit = ut1_.idx(1); } 
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    (void)(m_assertTrue(Args{m_magnet_gift(Args{L_b, L_unit}), SV("first activation fits the head")}));
    (void)(m_assertEqual(Args{rdm(L_unit, &Obj::防具, SV("防具")), SV("铁桶")}));
    (void)(m_assertFalse(Args{py::m_get(L_unit, pm_native_expansion::IMP_ARMOR), SV("the imp is left for a later activation")}));
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    (void)(m_assertTrue(Args{m_magnet_gift(Args{L_b, L_unit}), SV("second activation fits the imp")}));
    (void)(m_assertTrue(Args{py::m_get(L_unit, pm_native_expansion::IMP_ARMOR)}));
    (void)(m_assertEqual(Args{rd(L_unit, pm_native_expansion::IMP_ARMOR_HP), rdm(L_unit, &Obj::防具血量, SV("防具血量")), SV("same metal, same value")}));
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    (void)(m_assertFalse(Args{m_magnet_gift(Args{L_b, L_unit}), SV("both dressed, nothing left to fit")}));
    return V::none();
}

V C_GiantRidingImpHeadgearTests::m_test_magnet_strips_one_piece_at_a_time(const Args& A) {
    V L_b;
    V L_first;
    V L_unit;
    { V ut1_ = py::as_seq(m_giant(Args({}, {{SY("riding_armor"), V::none()}}))); L_b = ut1_.idx(0); L_unit = ut1_.idx(1); } 
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    (void)(m_magnet_gift(Args{L_b, L_unit}));
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    (void)(m_magnet_gift(Args{L_b, L_unit}));
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    L_first = m_magnet_absorb(Args{L_b, L_unit});
    (void)(m_assertEqual(Args{L_first, V::tuple({SV("armor"), V(true)}), SV("the head goes first")}));
    (void)(m_assertEqual(Args{rdm(L_unit, &Obj::防具, SV("防具")), SV("")}));
    (void)(m_assertTrue(Args{py::m_get(L_unit, pm_native_expansion::IMP_ARMOR), SV("the imp keeps its helmet for now")}));
    (void)(callm(L_b, SY("step"), Args{V(1.0)}));
    (void)(m_assertEqual(Args{m_magnet_absorb(Args{L_b, L_unit}), V::tuple({SV("imp"), V(true)}), SV("then the imp")}));
    (void)(m_assertFalse(Args{py::m_get(L_unit, pm_native_expansion::IMP_ARMOR)}));
    return V::none();
}

